/* 定义语法 */
font-family:字体族1,字体族2,…,通用字体族|inherit
/* 示例 */
font-family:Tahoma,"Microsoft YaHei","SimSun",Sans-Serif;

/* 宋体的 Unicode 写法（兼容 Firefox / Opera） */
font-family:tahoma,"microsoft yahei","\5b8b\4f53",sans-serif

/* 定义语法 */
font: font-style | font-variant | font-weight | font-size/line-height |
font-family;

/* 示例 */
font: italic bold 12px/2em "SimSun",sans-serif

/* 等价于 */
font-style:italic;
font-weight:bold;
font-size:12px;
line-height:2em;
font-family:"simsun",sans-serif;

@font-face{
  font-family:自定义字体的名称;
  src: url('fontfile_url');
}

/* 示例：定义 */
@font-face{
  font-family:qigong;
  src: url('assets/qigong.ttf');
}

/* 引用：名称必须完全一致 */
font-family:qigong;
